import{_ as e,c as a,a1 as i,o as t}from"./chunks/framework.CnnR69hl.js";const k=JSON.parse('{"title":"Linux Performance Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"linux-fundamentals/performance-analysis.md","filePath":"linux-fundamentals/performance-analysis.md"}'),n={name:"linux-fundamentals/performance-analysis.md"};function o(l,s,d,r,c,p){return t(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="linux-performance-analysis" tabindex="-1">Linux Performance Analysis <a class="header-anchor" href="#linux-performance-analysis" aria-label="Permalink to &quot;Linux Performance Analysis&quot;">​</a></h1><h2 id="কী-এবং-কেন" tabindex="-1">কী এবং কেন <a class="header-anchor" href="#কী-এবং-কেন" aria-label="Permalink to &quot;কী এবং কেন&quot;">​</a></h2><p>Linux system performance বুঝতে হলে আপনাকে CPU, memory, disk, এবং network usage দেখতে হবে। <code>top</code>, <code>htop</code>, <code>free</code>, <code>df</code>, <code>iostat</code>, <code>vmstat</code>, <code>ps</code>—এই tools দিয়ে আপনি বুঝতে পারবেন server কেমন কাজ করছে, কোথায় bottleneck আছে, আর কি কারণে system slow হচ্ছে।</p><p>Performance tuning শুরু হয় <strong>measure</strong> থেকে। আগে বুঝুন কোথায় resource বেশি ব্যবহার হচ্ছে, তারপর fix করুন।</p><h2 id="মূল-command-concept" tabindex="-1">মূল Command/Concept <a class="header-anchor" href="#মূল-command-concept" aria-label="Permalink to &quot;মূল Command/Concept&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>উদ্দেশ্য</th><th>উদাহরণ</th></tr></thead><tbody><tr><td><code>top</code></td><td>live process overview</td><td><code>top</code></td></tr><tr><td><code>htop</code></td><td>colorful interactive system monitor</td><td><code>htop</code></td></tr><tr><td><code>ps</code></td><td>running processes দেখা</td><td><code>ps -aux --sort=-%cpu</code></td></tr><tr><td><code>free -h</code></td><td>RAM usage দেখা</td><td><code>free -h</code></td></tr><tr><td><code>df -h</code></td><td>disk usage দেখা</td><td><code>df -h</code></td></tr><tr><td><code>du -sh</code></td><td>directory size দেখানো</td><td><code>du -sh /var/log</code></td></tr><tr><td><code>vmstat 1</code></td><td>virtual memory + CPU stats</td><td><code>vmstat 1</code></td></tr><tr><td><code>iostat 1</code></td><td>I/O statistics</td><td><code>iostat 1</code></td></tr><tr><td><code>uptime</code></td><td>load average দেখা</td><td><code>uptime</code></td></tr><tr><td><code>sar</code></td><td>historical performance data</td><td><code>sar -u 1 5</code></td></tr></tbody></table><h2 id="linux-performance-metrics-বুঝা" tabindex="-1">Linux performance metrics বুঝা <a class="header-anchor" href="#linux-performance-metrics-বুঝা" aria-label="Permalink to &quot;Linux performance metrics বুঝা&quot;">​</a></h2><h3 id="_1-cpu" tabindex="-1">1. CPU <a class="header-anchor" href="#_1-cpu" aria-label="Permalink to &quot;1. CPU&quot;">​</a></h3><ul><li><code>load average</code> = system কত busy</li><li>high CPU usually means process loop, heavy computation, or runaway service</li></ul><h3 id="_2-memory" tabindex="-1">2. Memory <a class="header-anchor" href="#_2-memory" aria-label="Permalink to &quot;2. Memory&quot;">​</a></h3><ul><li><code>free</code> দেখলে actual RAM usage ও cache বুঝতে পারবেন</li><li>cache memory ব্যবহার করে system performance বাড়াতে পারে</li></ul><h3 id="_3-disk" tabindex="-1">3. Disk <a class="header-anchor" href="#_3-disk" aria-label="Permalink to &quot;3. Disk&quot;">​</a></h3><ul><li><code>df -h</code> = filesystem full কিনা</li><li><code>iostat</code> = disk I/O bottleneck আছে কিনা</li></ul><h3 id="_4-processes" tabindex="-1">4. Processes <a class="header-anchor" href="#_4-processes" aria-label="Permalink to &quot;4. Processes&quot;">​</a></h3><ul><li><code>ps</code> + <code>top</code> দিয়ে identify high CPU or high memory processes</li></ul><h2 id="ছোট-বাস্তব-উদাহরণ" tabindex="-1">ছোট বাস্তব উদাহরণ <a class="header-anchor" href="#ছোট-বাস্তব-উদাহরণ" aria-label="Permalink to &quot;ছোট বাস্তব উদাহরণ&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ১. Current system overview</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uptime</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: 12:40:25 up 5 days,  3:15,  2 users,  load average: 1.20, 0.90, 0.75</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ২. RAM usage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">free</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># total used free shared buff/cache available</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Mem: 15Gi 6Gi 2Gi 0.1Gi 7Gi 8Gi</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ৩. CPU-heavy processes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sort=-%cpu</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: python, node, java, mysql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ৪. Disk usage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">df</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: /dev/sda1  50G 32G 15G 69%</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ৫. Memory-heavy directories</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: sizes of interesting directories</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ৬. Live monitoring</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Displays memory, CPU, IO stats every second</span></span></code></pre></div><h2 id="performance-bottleneck-identification" tabindex="-1">Performance bottleneck identification <a class="header-anchor" href="#performance-bottleneck-identification" aria-label="Permalink to &quot;Performance bottleneck identification&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU bottleneck      → high %CPU, rising load average</span></span>
<span class="line"><span>Memory bottleneck   → free memory very low, swap usage high</span></span>
<span class="line"><span>Disk bottleneck     → iowait high, slow I/O, df near full</span></span>
<span class="line"><span>Network bottleneck  → high rx/tx, high latency, slow SSH/API</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>top</code>/<code>htop</code> দেখেই অনেক performance issue দ্রুত detect হয়। কিন্তু শুধু one snapshot দেখে সিদ্ধান্ত করবেন না — multiple readings নিন, তারপর bottleneck নিশ্চিত করুন।</p></div><h2 id="সংক্ষিপ্ত-সারসংক্ষেপ" tabindex="-1">সংক্ষিপ্ত সারসংক্ষেপ <a class="header-anchor" href="#সংক্ষিপ্ত-সারসংক্ষেপ" aria-label="Permalink to &quot;সংক্ষিপ্ত সারসংক্ষেপ&quot;">​</a></h2><ul><li><code>top</code>/<code>htop</code> = live process ও CPU usage দেখা</li><li><code>free -h</code> = RAM status, <code>df -h</code> = disk status</li><li><code>ps</code> = specific process identify করা</li><li><code>vmstat</code> ও <code>iostat</code> = system-wide performance trend দেখা</li><li>high load average, high I/O wait, low available memory—সবই symptoms</li><li>performance debugging শুরু হয় data collection থেকে, তারপর root cause</li></ul>`,22)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
